    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"تعريف المحيط","math":"المحيط هو مجموع أطوال جميع الأضلاع"},{"quoi":"نجمع الأضلاع","math":"<span dir=\"ltr\" class=\"expr\">P = x + x + x + 6 + (x + 1)</span>"},{"quoi":"نزيل الأقواس","math":"<span dir=\"ltr\" class=\"expr\">P = x + x + x + 6 + x + 1</span>"},{"quoi":"نجمع حدود x","math":"مجموع حدود x يساوي 4 x"},{"quoi":"نجمع الأعداد","math":"مجموع الأعداد يساوي 7"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">P = 4 x + 7</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نعوّض في العبارة","math":"<span dir=\"ltr\" class=\"expr\">P = 4 × 8 + 7</span>"},{"quoi":"نحسب الجداء","math":"<span dir=\"ltr\" class=\"expr\">4 × 8 = 32</span>"},{"quoi":"نجمع","math":"<span dir=\"ltr\" class=\"expr\">32 + 7 = 39</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">P = 39</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">4 x + 7 = <span class=\"frac\"><span class=\"num\">49</span><span class=\"den\">3</span></span></span>"},{"quoi":"نطرح 7 من الطرفين","math":"<span dir=\"ltr\" class=\"expr\">4 x = <span class=\"frac\"><span class=\"num\">49</span><span class=\"den\">3</span></span> - 7</span>"},{"quoi":"نحسب الطرف الثاني","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">49</span><span class=\"den\">3</span></span> - 7 = <span class=\"frac\"><span class=\"num\">28</span><span class=\"den\">3</span></span></span>"},{"quoi":"نقسم على 4","math":"<span dir=\"ltr\" class=\"expr\">x = <span class=\"frac\"><span class=\"num\">28</span><span class=\"den\">3</span></span> : 4</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">3</span></span></span>"}],
